function merge(target, src) {
  for (const k of Object.keys(src)) {
    if (typeof src[k] === 'object' && src[k] !== null) {
      merge(target[k] = target[k] || {}, src[k]);
    } else {
      target[k] = src[k];
    }
  }
  return target;
}

